WITH DADOS_YTD AS (    SELECT        CTACTB,        SUM(CASE WHEN REFERENCIA BETWEEN :VAR_DATA_INICIO AND :VAR_DATA_FIM THEN VLRLANC ELSE 0 END) AS VALOR_ATUAL,        SUM(CASE WHEN REFERENCIA BETWEEN DATE_SUB(:VAR_DATA_INICIO, INTERVAL 1 YEAR) AND DATE_SUB(:VAR_DATA_FIM, INTERVAL 1 YEAR) THEN VLRLANC ELSE 0 END) AS VALOR_ANTERIOR    FROM IMP_BASE_BALANCETE    WHERE CODEMP = :VAR_EMPRESA_DRE      AND (CTACTB LIKE '3%' OR CTACTB LIKE '4%' OR CTACTB LIKE '5%')    GROUP BY CTACTB),REGRAS AS (    SELECT DISTINCT A.ORDEM, A.NOME_GRUPO, C.PADRAO_CTACTB, C.SINAL    FROM DET_DEMONSTRATIVO A    JOIN DET_DEMONSTRATIVO_REFERENCIA R ON A.ID = R.ID_DET_DEMONSTRATIVO    JOIN DET_DEMONSTRATIVO_CTACTB C ON R.ID = C.ID_DET_DEMONSTRATIVO_REFERENCIA    WHERE A.ID_ESTR_DEMONSTRATIVO = 4      AND R.ANO_REFERENCIA = (          SELECT MAX(R2.ANO_REFERENCIA)          FROM DET_DEMONSTRATIVO_REFERENCIA R2          WHERE R2.ID_DET_DEMONSTRATIVO = A.ID            AND R2.ANO_REFERENCIA <= YEAR(:VAR_DATA_FIM)      ))SELECT    R.ORDEM,    R.NOME_GRUPO,    SUM(IFNULL(D.VALOR_ATUAL, 0) * R.SINAL) AS VALOR_ATUAL,    SUM(IFNULL(D.VALOR_ANTERIOR, 0) * R.SINAL) AS VALOR_ANTERIORFROM REGRAS RLEFT JOIN DADOS_YTD D ON D.CTACTB LIKE R.PADRAO_CTACTBGROUP BY R.ORDEM, R.NOME_GRUPOORDER BY R.ORDEM